examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchSwitchRow(
        checked = first,
        onCheckedChange = { first = it },
        label = {{items.0.label}},
        description = {{items.0.description}},
    )
    MonarchSwitchRow(
        checked = second,
        onCheckedChange = { second = it },
        label = {{items.1.label}},
    )
}

